     ('membership in an inductively defined set, by structural recursion', "(define (member-of-list-set? x)\n  (cond ((null? x) #t)\n        ((pair? x) (member-of-list-set? (cdr x)))\n        (else #f)))\n(display (map member-of-list-set? (list (list 1 2) (cons 1 2) 7)))\n(newline)"),
